import java.time.Duration;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import static com.ruoyi.majorpilot.report.ReportStore.*;

@Service @Profile({"local","pilot"})
public class ReportService {
    private com.ruoyi.majorpilot.experience.MethodReports methods;
    @org.springframework.beans.factory.annotation.Autowired public void methodReports(com.ruoyi.majorpilot.experience.MethodReports value){methods=value;}
    private final ReportStore store;private final ReportCoordinator queue;private final NextRecommendations next;private final IdempotencyService idem;private final RateLimits limits;private final EvidenceRuleRegistry registry;
    public ReportService(ReportStore store,ReportCoordinator queue,NextRecommendations next,IdempotencyService idem,RateLimits limits,EvidenceRuleRegistry registry){this.store=store;this.queue=queue;this.next=next;this.idem=idem;this.limits=limits;this.registry=registry;}
    public ReportDtos.Generation generation(Map<String,Object> r){Map<String,Object> v;if(r.get("generation_target_version_id")!=null)v=store.version(n(r,"generation_target_version_id"));else{var last=store.db().queryForList("SELECT * FROM mp_report_version WHERE report_id=? ORDER BY version_no DESC LIMIT 1",n(r,"id"));if(last.isEmpty()||!"FAILED".equals(s(last.getFirst(),"status")))return null;v=last.getFirst();}return new ReportDtos.Generation(s(v,"status"),s(v,"generation_phase"),"GENERATING".equals(s(v,"status")),s(v,"failure_code"));}
    public ReportDtos.Status status(Map<String,Object> r){String current=r.get("current_version_id")==null?null:s(store.version(n(r,"current_version_id")),"public_id");return new ReportDtos.Status(s(r,"public_id"),s(r,"status"),current,generation(r),n(r,"row_version"));}
    public ReportDtos.Summary summary(Map<String,Object> r){var v=r.get("current_version_id")==null?null:store.version(n(r,"current_version_id"));return new ReportDtos.Summary(s(r,"public_id"),s(r,"report_type"),s(r,"major_code"),s(r,"status"),v==null?null:s(v,"public_id"),v==null?null:n(v,"version_no"),generation(r),time(r,"ready_at"),time(r,"first_ready_at"),n(r,"row_version"),r.get("experience_run_id")==null?null:store.db().queryForObject("SELECT public_id FROM mp_experience_run WHERE id=? AND student_id=?",String.class,n(r,"experience_run_id"),n(r,"student_id")));}
    private void readLimit(StudentPrincipal s){limits.require("report-read",s.publicId(),120,Duration.ofMinutes(1));}
    public ReportDtos.Page list(StudentPrincipal student,String cursor,Integer limit){readLimit(student);return store.tx().execute(status->{store.active(student.internalId());int size=limit==null?20:limit;if(size<1||size>50||cursor!=null&&!cursor.matches("[0-7][0-9A-HJKMNP-TV-Z]{25}"))throw new ApiException(422,"VALIDATION_ERROR");var rows=store.db().queryForList("SELECT r.*,m.code AS major_code FROM mp_report r LEFT JOIN mp_major m ON m.id=r.major_id WHERE r.student_id=? AND (? IS NULL OR r.public_id<?) ORDER BY r.public_id DESC LIMIT ?",student.internalId(),cursor,cursor,size+1);boolean more=rows.size()>size;var selected=rows.subList(0,Math.min(size,rows.size()));return new ReportDtos.Page(selected.stream().map(this::summary).toList(),more?s(selected.getLast(),"public_id"):null);});}
    public ReportDtos.Status status(StudentPrincipal student,String id){readLimit(student);return store.tx().execute(tx->{store.active(student.internalId());return status(store.owned(student.internalId(),id));});}
    public Object get(StudentPrincipal student,String id,String expectedVersion){readLimit(student);return store.tx().execute(tx->{store.active(student.internalId());var report=store.owned(student.internalId(),id);if(report.get("current_version_id")==null){if("FAILED".equals(s(report,"status"))){var failed=generation(report);throw new ApiException(409,failed!=null&&"PILOT_REPORT_LIMIT".equals(failed.safeCode())?"PILOT_REPORT_LIMIT":"REPORT_GENERATION_FAILED");}return status(report);}var v=store.version(n(report,"current_version_id"));if(expectedVersion!=null&&!expectedVersion.equals(s(v,"public_id")))throw new ApiException(409,"REPORT_VERSION_CHANGED");return body(v);});}
    JsonNode body(Map<String,Object> v){var body=store.node(v.get("structured_report_json"));if(!Set.of("READY","SUPERSEDED").contains(s(v,"status"))||!store.hash(body).equals(s(v,"report_body_sha256")))throw new ApiException(409,"REPORT_GENERATION_FAILED");return body;}
    public Object comparison(StudentPrincipal student){readLimit(student);return store.tx().execute(tx->{store.active(student.internalId());var reports=store.db().queryForList("SELECT * FROM mp_report WHERE student_id=? AND report_type='COMPARISON'",student.internalId());if(!reports.isEmpty()&&reports.getFirst().get("current_version_id")!=null){var r=reports.getFirst();return new ReportDtos.ComparisonReady("READY",body(store.version(n(r,"current_version_id"))),generation(r));}var states=store.db().queryForList("SELECT m.code,COALESCE(p.status,'NOT_REQUESTED') AS status FROM mp_major m LEFT JOIN mp_report p ON p.id=(SELECT rr.id FROM mp_report rr JOIN mp_experience_run er ON er.id=rr.experience_run_id WHERE rr.major_id=m.id AND rr.student_id=? AND rr.report_type='EXPERIENCE' ORDER BY er.experience_edition DESC,rr.id DESC LIMIT 1) ORDER BY m.code",student.internalId()).stream().map(r->new ReportDtos.MajorState(s(r,"code"),s(r,"status"))).toList();long count=states.stream().filter(m->!m.status().equals("NOT_REQUESTED")).count();String reason=!reports.isEmpty()?"FAILED".equals(s(reports.getFirst(),"status"))?"COMPARISON_FAILED":"COMPARISON_GENERATING":count<2?"NEED_TWO_MAJORS":states.stream().anyMatch(m->m.status().equals("FAILED"))?"SOURCE_REPORT_FAILED":"WAITING_SOURCE_REPORTS";return new ReportDtos.Waiting("WAITING",reason,states);});}
    public ReportDtos.Requested regenerate(long operator,String id,String key,ReportDtos.Regenerate input,String requestId){
        var rows=store.db().queryForList("SELECT * FROM mp_report WHERE public_id=?",id);if(rows.isEmpty())throw new ApiException(404,"RESOURCE_NOT_FOUND");long student=n(rows.getFirst(),"student_id");
        limits.require("report-regenerate",Long.toString(operator),5,Duration.ofMinutes(1));
        return idem.execute(new IdempotencyService.Owner(student,null,"operator:"+operator),"POST","/api/admin/v1/majorpilot/reports/"+id+"/regenerations",key,input,ReportDtos.Requested.class,()->{
            store.active(student);var report=store.db().queryForMap("SELECT * FROM mp_report WHERE id=? FOR UPDATE",n(rows.getFirst(),"id"));
            if(input.expectedRevision()==null||input.expectedRevision()!=n(report,"row_version"))throw new ApiException(409,"REPORT_REVISION_CONFLICT",Map.of("currentRevision",n(report,"row_version")));
            if(input.reasonCode()==null||!Set.of("CONTENT_CORRECTION","GENERATION_FAILURE","RULE_UPDATE","OPERATOR_REQUEST").contains(input.reasonCode())||input.reason()==null||input.reason().codePointCount(0,input.reason().length())<10||input.reason().codePointCount(0,input.reason().length())>500||!Set.of("REUSE_READY_EVIDENCE","REBUILD_EVIDENCE").contains(input.evidenceMode()==null?"":input.evidenceMode()))throw new ApiException(422,"VALIDATION_ERROR");
            if(report.get("generation_target_version_id")!=null)throw new ApiException(409,"REPORT_REGENERATION_IN_PROGRESS");
            boolean rebuild=input.evidenceMode().equals("REBUILD_EVIDENCE"),comparison=s(report,"report_type").equals("COMPARISON");
            var latestSchema=store.db().queryForList("SELECT schema_version FROM mp_report_version WHERE report_id=? ORDER BY version_no DESC LIMIT 1",n(report,"id"));
            if(!comparison&&methods!=null&&!latestSchema.isEmpty()&&"method-report-v1".equals(latestSchema.getFirst().get("schema_version"))){if(rebuild||input.targetEvidenceRuleVersion()!=null)throw new ApiException(422,"EVIDENCE_RULE_UNSUPPORTED");var v=methods.regenerate(student,id);audit(operator,report,input,requestId,s(v,"public_id"));return new ReportDtos.Requested(id,s(v,"public_id"),"GENERATING",n(store.report(n(report,"id")),"row_version"));}
            if(comparison&&rebuild||!rebuild&&input.targetEvidenceRuleVersion()!=null)throw new ApiException(422,"EVIDENCE_RULE_UNSUPPORTED");
            if(comparison){queue.compare(student,true);var refreshed=store.report(n(report,"id"));if(refreshed.get("generation_target_version_id")==null)throw new ApiException(409,"REPORT_REGENERATION_IN_PROGRESS");var v=store.version(n(refreshed,"generation_target_version_id"));audit(operator,report,input,requestId,s(v,"public_id"));return new ReportDtos.Requested(id,s(v,"public_id"),"GENERATING",n(refreshed,"row_version"));}
            long run=n(report,"experience_run_id");var r=store.db().queryForMap("SELECT r.* FROM mp_experience_run r WHERE r.id=? AND r.student_id=? AND "+ProductEligibility.sql("r")+" AND r.status='CLOSED'",run,student);var closed=store.node(r.get("closed_input_manifest_json"));
            String effective=rebuild?input.targetEvidenceRuleVersion():null;if(rebuild&&(effective==null||!Set.of("evidence-v3","ds-evidence-v2","ba-evidence-v2").contains(effective)))throw new ApiException(422,"EVIDENCE_RULE_UNSUPPORTED");
            if(rebuild){var task=store.db().queryForMap("SELECT t.public_id,t.manifest_sha256,t.manifest_json,m.code FROM mp_task_version t JOIN mp_major m ON m.id=t.major_id WHERE t.id=?",n(r,"task_version_id"));try{registry.requireCompatible(closed.path("evidenceRuleVersion").asText(),effective,closed.path("schemaVersion").asText(),s(task,"code"),s(task,"public_id"),s(task,"manifest_sha256"),store.node(task.get("manifest_json")).path("reflection").path("questionSetVersion").asText());}catch(ReportInputException unsupported){throw new ApiException(422,"EVIDENCE_RULE_UNSUPPORTED");}}
            var request=map("schemaVersion","report-request-v1","reportId",id,"reportType","EXPERIENCE","runId",s(r,"public_id"),"closedInputSha256",s(r,"closed_input_sha256"),"evidenceMode",input.evidenceMode(),"targetEvidenceRuleVersion",effective,"nextRecommendation",next.projection(student,run),"sourceVersionIds",List.of());
            List<Source> sources=null;if(!rebuild){var prior=report.get("current_version_id")!=null?List.of(store.version(n(report,"current_version_id"))):store.db().queryForList("SELECT * FROM mp_report_version WHERE report_id=? AND input_manifest_json IS NOT NULL ORDER BY version_no DESC LIMIT 1",n(report,"id"));if(prior.isEmpty())throw new ApiException(409,"REPORT_EVIDENCE_NOT_READY");var original=store.input(prior.getFirst());store.verifyInput(original,false);sources=original.sources();request.put("targetEvidenceRuleVersion",sources.getFirst().snapshot().effectiveRule());}
            var version=queue.create(report,request);if(rebuild){store.db().update("INSERT INTO mp_background_job(public_id,job_type,business_key,owner_student_id,target_type,target_id,checkpoint_json) VALUES(?,'EVIDENCE_REBUILD',?,?,'REPORT_VERSION',?,?)",PublicIds.next(),"evidence-regeneration:"+s(version,"public_id")+":"+s(version,"request_manifest_sha256"),student,n(version,"id"),store.json(map("reportVersionId",s(version,"public_id"),"sourceRule",closed.path("evidenceRuleVersion").asText(),"effectiveRule",effective)));}else queue.prepare(report,version,sources);
            audit(operator,report,input,requestId,s(version,"public_id"));return new ReportDtos.Requested(id,s(version,"public_id"),"GENERATING",n(store.report(n(report,"id")),"row_version"));
        }).data();
    }
    private void audit(long operator,Map<String,Object> report,ReportDtos.Regenerate input,String requestId,String version){store.db().update("INSERT INTO mp_sensitive_audit(public_id,operator_id,owner_student_id,action_code,target_type,target_public_id,reason_code,reason_text,before_summary_json,after_summary_json,correlation_id) VALUES(?,?,?,'REPORT_REGENERATE','REPORT',?,?,?,?,?,?)",PublicIds.next(),operator,n(report,"student_id"),s(report,"public_id"),input.reasonCode(),input.reason(),store.json(map("revision",n(report,"row_version"))),store.json(map("reportVersionId",version)),requestId);}
    public Object adminGet(String id){var rows=store.db().queryForList("SELECT r.*,m.code AS major_code FROM mp_report r LEFT JOIN mp_major m ON m.id=r.major_id WHERE r.public_id=?",id);if(rows.isEmpty())throw new ApiException(404,"RESOURCE_NOT_FOUND");return summary(rows.getFirst());}
    public Object adminList(){return store.db().queryForList("SELECT r.*,m.code AS major_code FROM mp_report r LEFT JOIN mp_major m ON m.id=r.major_id ORDER BY r.id DESC LIMIT 50").stream().map(this::summary).toList();}
    public Object history(String id){var rows=store.db().queryForList("SELECT id FROM mp_report WHERE public_id=?",id);if(rows.isEmpty())throw new ApiException(404,"RESOURCE_NOT_FOUND");return store.db().queryForList("SELECT public_id,version_no,status,generation_phase,generation_mode,failure_code,created_at,completed_at FROM mp_report_version WHERE report_id=? ORDER BY version_no DESC LIMIT 50",n(rows.getFirst(),"id")).stream().map(v->map("reportVersionId",s(v,"public_id"),"versionNo",n(v,"version_no"),"status",s(v,"status"),"generationMode",s(v,"generation_mode"),"failureCode",s(v,"failure_code"),"createdAt",time(v,"created_at"),"completedAt",time(v,"completed_at"))).toList();}
    public Object sensitive(long operator,String id,String version,String request){return store.tx().execute(tx->{var rows=store.db().queryForList("SELECT v.*,r.student_id FROM mp_report_version v JOIN mp_report r ON r.id=v.report_id WHERE r.public_id=? AND v.public_id=?",id,version);if(rows.isEmpty())throw new ApiException(404,"RESOURCE_NOT_FOUND");var body=body(rows.getFirst());store.db().update("INSERT INTO mp_sensitive_audit(public_id,operator_id,owner_student_id,action_code,target_type,target_public_id,reason_code,reason_text,before_summary_json,after_summary_json,correlation_id) VALUES(?,?,?,'REPORT_SENSITIVE_READ','REPORT_VERSION',?,'AUTHORIZED_SUPPORT','Permission-scoped report version read','{}','{}',?)",PublicIds.next(),operator,n(rows.getFirst(),"student_id"),version,request);return body;});}
}
